param(
    [string]$ProjectRoot = (Resolve-Path "$PSScriptRoot\..").Path,
    [string]$ResolvedPlanPath = "assembly\resolved-plan.json",
    [string]$IRPath = "",
    [string]$OutputDirectory = "assembly\backend-registry"
)

$ErrorActionPreference = "Stop"

function Read-JsonUtf8([string]$Path) {
    return Get-Content -Raw -Encoding UTF8 $Path | ConvertFrom-Json
}

function ConvertTo-PythonString([string]$Value) {
    if ([string]::IsNullOrWhiteSpace($Value)) {
        return "None"
    }
    return "'" + $Value.Replace("\", "\\").Replace("'", "\'") + "'"
}

function ConvertTo-PythonStringList([object[]]$Values) {
    $items = @($Values | ForEach-Object { ConvertTo-PythonString ([string]$_) })
    return "[" + ($items -join ", ") + "]"
}

function ConvertTo-PythonBool([bool]$Value) {
    if ($Value) {
        return "True"
    }
    return "False"
}

function ConvertTo-SettingsName([string]$Value) {
    if ([string]::IsNullOrWhiteSpace($Value)) {
        return ""
    }
    return $Value.ToLowerInvariant()
}

$resolvedPlanFullPath = Join-Path $ProjectRoot $ResolvedPlanPath
$outputFullPath = Join-Path $ProjectRoot $OutputDirectory

$irFullPath = if ([string]::IsNullOrWhiteSpace($IRPath)) { "" } else { Join-Path $ProjectRoot $IRPath }
if (-not [string]::IsNullOrWhiteSpace($irFullPath) -and (Test-Path $irFullPath)) {
    $ir = Read-JsonUtf8 $irFullPath
    $registrations = @($ir.backend.routerRegistrations)
} else {
    $plan = Read-JsonUtf8 $resolvedPlanFullPath
    $registrations = @($plan.backendRouterRegistrations)
}

$hasPlatformCore = @($registrations | Where-Object { [string]$_.kit -eq "platform-core-kit" }).Count -gt 0
$hasKitBroker = @($registrations | Where-Object { [string]$_.module -eq "app.api.routes_kit_broker" }).Count -gt 0
if ($hasPlatformCore -and -not $hasKitBroker) {
    $registrations += [pscustomobject]@{
        kit = "platform-core-kit"
        module = "app.api.routes_kit_broker"
        symbol = "router"
        prefix = "/api/kit"
        tags = @("Kit Broker")
        tenantScoped = $false
        featureFlag = $null
    }
}

# Filter out registrations whose Python source file does not exist in the assembled backend.
# This only applies when $OutputDirectory points at the assembled tree (assemble-system.ps1's
# call site) - other callers (test-all.ps1, extract-mvp-flow.ps1) use the default resolved-plan
# location, where there is no sibling "backend" directory to check against, and the filter must
# be skipped rather than treated as "everything is missing".
$assembledBackendDir = Join-Path (Split-Path (Split-Path $outputFullPath -Parent) -Parent) "backend"
if (Test-Path $assembledBackendDir) {
    $registrations = @($registrations | Where-Object {
        $moduleRelPath = ([string]$_.module).Replace('.', '\') + '.py'
        $exists = Test-Path (Join-Path $assembledBackendDir $moduleRelPath)
        if (-not $exists) {
            Write-Host "generate-backend-registry: skipping $([string]$_.module) (source not found in assembled backend)"
        }
        $exists
    })
}

if (-not (Test-Path $outputFullPath)) {
    New-Item -ItemType Directory -Force $outputFullPath | Out-Null
}

$jsonPath = Join-Path $outputFullPath "backend-router-registry.json"
$registrations | ConvertTo-Json -Depth 20 | Set-Content -Encoding UTF8 $jsonPath

$lines = New-Object System.Collections.Generic.List[string]
$lines.Add("# Generated by tools/generate-backend-registry.ps1")
$lines.Add("from __future__ import annotations")
$lines.Add("")
$lines.Add("from dataclasses import dataclass")
$lines.Add("from importlib import import_module")
$lines.Add("from typing import Any")
$lines.Add("")
$lines.Add("")
$lines.Add("@dataclass(frozen=True)")
$lines.Add("class BackendRouterRegistration:")
$lines.Add("    kit: str")
$lines.Add("    module: str")
$lines.Add("    symbol: str")
$lines.Add("    prefix: str | None")
$lines.Add("    tags: list[str]")
$lines.Add("    tenant_scoped: bool")
$lines.Add("    feature_flag: str | None = None")
$lines.Add("")
$lines.Add("")
$lines.Add("ROUTER_REGISTRY = [")

foreach ($registration in $registrations) {
    $lines.Add("    BackendRouterRegistration(")
    $lines.Add("        kit=$(ConvertTo-PythonString ([string]$registration.kit)),")
    $lines.Add("        module=$(ConvertTo-PythonString ([string]$registration.module)),")
    $lines.Add("        symbol=$(ConvertTo-PythonString ([string]$registration.symbol)),")
    $lines.Add("        prefix=$(ConvertTo-PythonString ([string]$registration.prefix)),")
    $lines.Add("        tags=$(ConvertTo-PythonStringList @($registration.tags)),")
    $lines.Add("        tenant_scoped=$(ConvertTo-PythonBool ([bool]$registration.tenantScoped)),")
    $lines.Add("        feature_flag=$(ConvertTo-PythonString (ConvertTo-SettingsName ([string]$registration.featureFlag))),")
    $lines.Add("    ),")
}

$lines.Add("]")
$lines.Add("")
$lines.Add("")
$lines.Add("def register_backend_routers(app: Any, *, tenant_deps: list[Any], settings: Any) -> None:")
$lines.Add("    for item in ROUTER_REGISTRY:")
$lines.Add("        if item.feature_flag and not bool(getattr(settings, item.feature_flag.lower(), False)):")
$lines.Add("            continue")
$lines.Add("        module = import_module(item.module)")
$lines.Add("        router = getattr(module, item.symbol)")
$lines.Add("        kwargs: dict[str, Any] = {'tags': item.tags}")
$lines.Add("        if item.prefix:")
$lines.Add("            kwargs['prefix'] = item.prefix")
$lines.Add("        if item.tenant_scoped:")
$lines.Add("            kwargs['dependencies'] = tenant_deps")
$lines.Add("        app.include_router(router, **kwargs)")
$lines.Add("")

$pythonPath = Join-Path $outputFullPath "backend_router_registry.py"
$lines -join [Environment]::NewLine | Set-Content -Encoding UTF8 $pythonPath

Write-Host "Backend router registry JSON written to $jsonPath"
Write-Host "Backend router registry Python written to $pythonPath"
